(3429, 62, 'product_details', '<table style=\"width: 100%; border-collapse: collapse;\" border=\"1\">\r\n<thead>\r\n<tr style=\"background-color: #f5f5f5;\">\r\n<th style=\"padding: 4px; border: 1px solid #ddd;\">Description</th>\r\n<th style=\"padding: 4px; border: 1px solid #ddd;\">Unisex Basic Softstyle</th>\r\n<th style=\"padding: 4px; border: 1px solid #ddd;\">Unisex Classic</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>General</b></td>\r\n<td style=\"border: 1px solid #ddd;\">Best choice for everyday wear</td>\r\n<td style=\"border: 1px solid #ddd;\">Classic streetwear fit, heavier weight</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>Composition</b></td>\r\n<td style=\"border: 1px solid #ddd;\">100% cotton</td>\r\n<td style=\"border: 1px solid #ddd;\">100% cotton</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>Fabric weight</b></td>\r\n<td style=\"border: 1px solid #ddd;\">153 g/m²</td>\r\n<td style=\"border: 1px solid #ddd;\">170–180 g/m²</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>Construction</b></td>\r\n<td style=\"border: 1px solid #ddd;\">Double-stitched hem and sleeves, no side seams</td>\r\n<td style=\"border: 1px solid #ddd;\">Double-stitched hem, no side seams</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>Fit</b></td>\r\n<td style=\"border: 1px solid #ddd;\">Regular unisex</td>\r\n<td style=\"border: 1px solid #ddd;\">Classic unisex \"boxer\"</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>Sizes</b></td>\r\n<td style=\"border: 1px solid #ddd;\">XS–3XL</td>\r\n<td style=\"border: 1px solid #ddd;\">XS–3XL</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ddd;\"><b>Safety</b></td>\r\n<td style=\"border: 1px solid #ddd;\" colspan=\"2\">Free from harmful polyester and hazardous substances</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
